// ===== CONFIG — edite os valores abaixo antes de ativar o workflow =====
return [{
  json: {
    clickupBaseUrl: "https://api.clickup.com/api/v2",
    clickupListId: "901321051391",

    // Campos já existentes no ClickUp (não mexer)
    fieldTarefasSkill: "036acdcf-df5a-4a6f-a944-3845236cd64a",
    valorSkillCaptacao: "5f1d6dd8-7738-4754-a0b9-a033b8be380b",
    fieldNomeCaptado: "5eac4259-559b-4faa-bae0-b5d544a1a040",

    // Campos NOVOS — criar manualmente no ClickUp (lista House Quatro5) e colar o UUID aqui.
    // "Estágio do lembrete": tipo number ou dropdown, valores 0 a 4 (ver README-n8n.md).
    fieldEstagioLembrete: "d898626d-ae5a-4d4f-89c4-5e75f8a74f1e",
    // "Whatsapp Captado" (tipo phone) — o mesmo UUID usado em lib/config.ts do site.
    fieldTelefoneCaptado: "ec822183-eb29-4434-9dd3-4c36276135ea",

    // UAZAPI
    uazapiBaseUrl: "https://SEU-DOMINIO.uazapi.com",

    // Planilha Google "Contatos de Captação" (colunas: Telefone, Nome, Já Recebeu Apresentação, Data da Primeira Captação)
    googleSheetsSpreadsheetId: "1tYkmBMk2A6Gpw6rJtCpT_bQeC-k2X1QtNVivJf0VkmU",
    googleSheetsContatosTab: "Contatos de Captação",
    googleSheetsLogTab: "Log"
  }
}];

// Cruza as captações do ClickUp com o estágio de lembrete de cada uma, decide se
// precisa mandar confirmação/lembrete agora, e monta o(s) texto(s) da mensagem.
// "Estágio do lembrete": 0 nada / 1 confirmação enviada / 2 lembrete 1 dia / 3 lembrete 2h / 4 lembrete 30min
// (extensão do rascunho original — a confirmação inicial também usa esse contador, como estágio 1)
const config = $('CONFIG').first().json;
const clickupResp = $('ClickUp: Buscar Captações').first().json;
const tasks = clickupResp.tasks || [];
const contatos = $('Ler Contatos').all().map(i => i.json);
const nowMs = Date.now();
const MESES = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];

function getCF(task, fieldId) {
  if (!fieldId) return null;
  const cf = (task.custom_fields || []).find(f => f.id === fieldId);
  return cf ? cf.value : null;
}
function parseDescField(desc, label) {
  const re = new RegExp('^' + label + ':\\s*(.+)$', 'm');
  const m = (desc || '').match(re);
  return m ? m[1].trim() : '';
}
function toFortaleza(ms) {
  const shifted = new Date(ms - 3 * 60 * 60 * 1000);
  return {
    dia: String(shifted.getUTCDate()).padStart(2, '0'),
    mesLabel: MESES[shifted.getUTCMonth()],
    hora: String(shifted.getUTCHours()).padStart(2, '0'),
    minuto: String(shifted.getUTCMinutes()).padStart(2, '0'),
  };
}

const results = [];

for (const task of tasks) {
  if (!task.start_date) continue;
  const startMs = Number(task.start_date);
  const diffMin = (startMs - nowMs) / 60000;
  if (diffMin < -15) continue; // já passou (com folga de 1 ciclo do poll) — não manda mais nada

  const estagioRaw = getCF(task, config.fieldEstagioLembrete);
  const estagio = estagioRaw != null && estagioRaw !== '' ? Number(estagioRaw) : 0;

  let novoEstagio = null;
  let tipoMensagem = null;
  if (estagio < 1) {
    novoEstagio = 1; tipoMensagem = 'confirmacao';
  } else if (estagio < 2 && diffMin <= 24 * 60) {
    novoEstagio = 2; tipoMensagem = 'lembrete_1dia';
  } else if (estagio < 3 && diffMin <= 120) {
    novoEstagio = 3; tipoMensagem = 'lembrete_2h';
  } else if (estagio < 4 && diffMin <= 30) {
    novoEstagio = 4; tipoMensagem = 'lembrete_30min';
  }
  if (!tipoMensagem) continue; // ainda não é hora de nada pra essa captação

  const telefoneRaw = getCF(task, config.fieldTelefoneCaptado);
  if (!telefoneRaw) continue; // sem WhatsApp cadastrado na task — não dá pra mandar (avaliar log manual)
  const telefone = String(telefoneRaw).replace(/\D/g, '');

  const nomeCaptado = (getCF(task, config.fieldNomeCaptado) || '').toString().trim() || 'tudo bem';
  const marcaMatch = (task.name || '').match(/^\[CAPTAÇÃO\]\s*([^-]+?)\s*-/);
  const marca = marcaMatch ? marcaMatch[1].trim() : '';
  const desc = task.text_content || task.description || '';
  const local = parseDescField(desc, 'Local') || 'local a confirmar';
  const { dia, mesLabel, hora, minuto } = toFortaleza(startMs);
  const dataFmt = `${dia} ${mesLabel}`;
  const horaFmt = `${hora}:${minuto}`;

  const textos = {
    confirmacao: `Oi, ${nomeCaptado}! Sua captação para ${marca} está marcada: ${dataFmt} às ${horaFmt}, em ${local}. Se precisar remarcar, responda "Adiar captação" com pelo menos 1h de antecedência.`,
    lembrete_1dia: `Lembrete: sua captação (${marca}) é amanhã, ${dataFmt}, às ${horaFmt}, em ${local}.`,
    lembrete_2h: `Sua captação (${marca}) é daqui a 2 horas, às ${horaFmt}, em ${local}.`,
    lembrete_30min: `Sua captação (${marca}) começa em 30 minutos, em ${local}. Já pode ir chegando.`,
  };

  const contato = contatos.find(c => String(c.Telefone || '').replace(/\D/g, '') === telefone);
  const jaRecebeuApresentacao = contato && String(contato['Já Recebeu Apresentação'] || '').toLowerCase().trim() === 'sim';

  const mensagens = [];
  if (!jaRecebeuApresentacao) {
    mensagens.push('Oi! Aqui é o assistente de captação do Grupo SB. A partir de agora você vai receber por aqui a confirmação e os lembretes das suas gravações. Qualquer dúvida, é só responder essa mensagem.');
  }
  mensagens.push(textos[tipoMensagem]);

  results.push({
    json: {
      taskId: task.id,
      telefone,
      nomeCaptado,
      tipoMensagem,
      novoEstagio,
      mensagens,
      precisaMarcarApresentacao: !jaRecebeuApresentacao,
      dataFmt,
    }
  });
}

return results;
